pub fn list_instructions() -> impl Iterator<Item = Instruction> {
    INSTRUCTIONS.iter().copied()
}

/// A register of a CPUID result.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum CpuidRegister {
    Eax,
    Ebx,
    Ecx,
    Edx,
}

/// A field of a CPUID result that must hold a value for a form to execute, under XED's name for it.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct CpuidRequirement {
    pub name: &'static str,
    pub leaf: u32,
    pub subleaf: u32,
    pub register: CpuidRegister,
    pub lowest_bit: u8,
    pub highest_bit: u8,
    pub value: u32,
}

